WITH eu AS (SELECT e.id AS executivo_id, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT count(p.id) AS total, count(p.id) FILTER (WHERE p.status = 'na_fila') AS na_fila, count(p.id) FILTER (WHERE p.status IN ('extraindo', 'curadoria', 'aguardando_anexo', 'criando')) AS andamento, count(p.id) FILTER (WHERE p.status = 'concluido') AS concluidos, count(p.id) FILTER (WHERE p.status IN ('falhou', 'precisa_catalogo')) AS falharam, avg(EXTRACT(EPOCH FROM (p.concluido_em - p.criado_em))) FILTER (WHERE p.status = 'concluido') AS tempo_medio_s, count(p.id) FILTER (WHERE p.status = 'concluido' AND p.concluido_em > now() - interval '24 hours') AS concluidos_24h FROM pedidos p JOIN eu ON (eu.admin OR p.executivo_id = eu.executivo_id) WHERE p.automatico
